#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        ll n;
        cin >> n;

        ll divisor = n;
        for (ll i = 2; i <= n / i; ++i) {
            if (n % i == 0) {
                divisor = i;
                break;
            }
        }

        ll a = n / divisor;
        cout << a << ' ' << n - a << '\n';
    }

    return 0;
}

